import json
import sys
import os

def escape_html(text):
    escape_map = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;'
    }
    return ''.join(escape_map.get(c, c) for c in text)

def main():
    token = sys.stdin.readline().strip()
    username = sys.stdin.readline().strip()

    try:
        with open('tokens.json', 'r') as f:
            tokens = json.load(f)
    except FileNotFoundError:
        sys.exit(1)

    if username not in tokens or tokens[username] != token:
        sys.exit(1)

    try:
        with open(f'records/{username}.json', 'r') as f:
            records = json.load(f)
    except FileNotFoundError:
        sys.exit(1)

    html_lines = [
        f'<h1>Report for {escape_html(username)}</h1>',
        '<ul>'
    ]

    for record in records:
        label = record.get('label', '')
        value = record.get('value', '')
        html_lines.append(f'<li>{escape_html(label)}: {escape_html(value)}</li>')

    html_lines.append('</ul>')

    print('\n'.join(html_lines))

if __name__ == '__main__':
    main()

import json
import sys

def main():
    token = sys.stdin.readline().strip()
